<script setup>import AppShell from '../components/AppShell.vue';import StatusPill from '../components/StatusPill.vue';import {orders,quality,rfqs} from '../api/mock';const props=defineProps({mode:String,module:String});const titles={orders:['采购订单','跟踪订单确认、变更与执行状态'],delivery:['交付监控','管理送货预约、收货进度与延期预警'],quality:['质量管理','闭环处理来料异常、整改与效果验证'],finance:['对账开票','核对结算数据并跟踪发票状态'],profile:['企业资料','维护企业资质、联系人与供货能力'],sourcing:['寻源与定价','管理询价、澄清、评审与定标过程'],performance:['绩效评价','按质量、交付、成本与服务综合评价'],risk:['风险中心','识别经营、交付、质量与合规风险']};const meta=titles[props.module]||['采购协同','业务协同与过程跟踪'];const data=props.module==='quality'?quality:props.module==='sourcing'?rfqs:orders</script>
<template><AppShell :mode="mode"><div class="page-head"><div><span class="breadcrumb">{{mode==='portal'?'供应商门户':'采购协同'}} / {{meta[0]}}</span><h1>{{meta[0]}}</h1><p>{{meta[1]}}</p></div><button class="primary">+ 新建业务单</button></div><section class="panel list-panel"><div class="toolbar"><div class="tabs"><button class="active">全部 <em>{{data.length}}</em></button><button>待处理</button><button>已完成</button></div><div class="filters"><input placeholder="输入编号或关键字"/><select><option>全部状态</option></select><button class="secondary">查询</button></div></div><table><thead><tr><th>业务编号</th><th>业务内容</th><th>负责人 / 金额</th><th>计划日期</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="(item,i) in data" :key="i"><td><b>{{item.no}}</b></td><td>{{item.title||item.item}}</td><td>{{item.owner||item.amount}}</td><td>{{item.deadline||item.date||item.due}}</td><td><StatusPill :text="item.status"/></td><td><button class="link-button">查看详情</button></td></tr></tbody></table></section></AppShell></template>
